public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        result.add(new ArrayList<>());
        return result;
    }
    List<Integer> permutation = new ArrayList<>();
    permutation.add(nums[0]);
    result.add(permutation);
    for (int i = 1; i < nums.length; i++) {
        int n = nums[i];
        List<List<Integer>> newResult = new ArrayList<>();
        for (List<Integer> perm : result) {
            for (int j = 0; j <= perm.size(); j++) {
                List<Integer> newPerm = new ArrayList<>(perm);
                newPerm.add(j, n);
                newResult.add(newPerm);
            }
        }
        result = newResult;
    }
    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    if (nums.length == 0) {
        return permutations;
    }
    permuteHelper(nums, 0, nums.length - 1, permutations);
    return permutations;
}

private void permuteHelper(int[] nums, int left, int right, List<List<Integer>> permutations) {
    if (left == right) {
        List<Integer> permutation = new ArrayList<>();
        for (int num : nums) {
            permutation.add(num);
        }
        permutations.add(permutation);
    } else {
        for (int i = left; i <= right; i++) {
            swap(nums, left, i);
            permuteHelper(nums, left + 1, right, permutations);
            swap(nums, left, i);
        }
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

