public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    // Base case: if the input array is empty, return an empty list
    if (nums.length == 0) {
        return permutations;
    }
    // Initialize a list to store the current permutation
    List<Integer> currentPermutation = new ArrayList<>();
    // Iterate over the input array
    for (int i = 0; i < nums.length; i++) {
        // If the current element is not already in the current permutation, add it
        if (!currentPermutation.contains(nums[i])) {
            currentPermutation.add(nums[i]);
        }
        // If the current permutation is a valid permutation of the input array, add it to the list of permutations
        if (isValidPermutation(currentPermutation, nums)) {
            permutations.add(new ArrayList<>(currentPermutation));
        }
        // Backtrack and try the next element in the input array
        currentPermutation.remove(currentPermutation.size() - 1);
    }
    return permutations;
}

private boolean isValidPermutation(List<Integer> permutation, int[] nums) {
    // Check if the permutation contains all elements of the input array
    for (int i = 0; i < nums.length; i++) {
        if (!permutation.contains(nums[i])) {
            return false;
        }
    }
    // Check if the permutation has no duplicates
    for (int i = 0; i < permutation.size(); i++) {
        for (int j = i + 1; j < permutation.size(); j++) {
            if (permutation.get(i).equals(permutation.get(j))) {
                return false;
            }
        }
    }
    return true;
}

