    // check if the start and end points are valid
    if (!isValid(start) || !isValid(end)) {
        return "cannot be travelled";
    }

    // create a copy of the paths array and remove the paths that are not reachable
    int[][] reachablePaths = new int[paths.length][paths[0].length];
    for (int i = 0; i < paths.length; i++) {
        reachablePaths[i] = paths[i].clone();
    }
    for (int i = 0; i < reachablePaths.length; i++) {
        for (int j = 0; j < reachablePaths[i].length; j++) {
            if (reachablePaths[i][j] >= reachablePaths[i][j + 1]) {
                reachablePaths[i][j] = -1;
            }
        }
    }

    // check if the end point is reachable
    boolean reachable = false;
    for (int i = 0; i < reachablePaths.length; i++) {
        if (reachablePaths[i][end[0] - 1] >= 0) {
            reachable = true;
            break;
        }
    }

    return reachable ? "can be travelled" : "cannot be travelled";
}

