public double trimMean(int[] arr) {
    // Calculate the mean of the array
    double mean = 0.0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= arr.length;

    // Calculate the 5% trim
    int trimAmount = Math.max(5, 5);
    int trimIndices = (int) Math.round(arr.length * 0.05);
    int[] trimIndicesArr = new int[trimIndices];
    for (int i = 0; i < trimIndices; i++) {
        trimIndicesArr[i] = i;
    }
    int[] truncatedIndices = new int[arr.length - 2 * trimIndices];
    for (int i = trimIndices; i < arr.length - trimIndices; i++) {
        truncatedIndices[i - trimIndices] = arr[i];
    }
    double trim = 0.0;
    for (int i = 0; i < trimIndices; i++) {
        trim += arr[trimIndicesArr[i]];
    }
    trim = trim / trimIndices;

    // Calculate the mean of the trimmed array
    double trimMean = 0.0;
    for (int i = 0; i < truncatedIndices.length; i++) {
        trimMean += truncatedIndices[i];
    }
    trimMean /= truncatedIndices.length;

    // Return the trim mean with an error within 10^-5
    return trimMean * (1 - 2 * trim / mean);
}

