public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] parent = new int[n];
    int[] depth = new int[n];
    int[] hasAppleCount = new int[n];

    // Initialize the parent and depth arrays
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        depth[i] = 0;
        hasAppleCount[i] = 0;
    }

    // Find the root node
    int root = -1;
    for (int i = 0; i < n; i++) {
        if (parent[i] == i) {
            root = i;
            break;
        }
    }

    // Find the time required to collect all apples
    int time = 0;
    for (int i = 1; i < n; i++) {
        int currDepth = depth[i];
        int currHasApple = hasAppleCount[i];

        // If the current node has an apple, add the time required to collect it
        if (hasApple[i]) {
            time += currHasApple;
        }

        // If the current node is the root, add the time required to reach the root node
        if (i == root) {
            time += currDepth;
        }
    }

    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize the minimum time to 0
  int minTime = 0;

  // Traverse the graph and collect apples
  for (int i = 1; i < n; i++) {
    if (hasApple[i]) {
      // If the current node has an apple, add the weight of the edge from the previous node to the current node
      minTime += edges[i - 1][i];
    }
  }

  // Return the minimum time required to collect all the apples and return to node 0
  return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the minimum time required to collect all the apples and return to node 0
    int minTime = 0;

    // Iterate through the edges and collect the apples
    for (int i = 0; i < edges.length; i++) {
        int start = edges[i][0];
        int end = edges[i][1];

        if (hasApple[start] || hasApple[end]) {
            minTime += 2;
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return minTime;
}

public String sortString(String s) {
    if (s.length() <= 1) {
        return s;
    }

    char smallest = s.charAt(0);
    char largest = s.charAt(s.length() - 1);
    String result = "";

    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c < smallest) {
            smallest = c;
        } else if (c > largest) {
            largest = c;
        }
    }

    while (count < s.length()) {
        char c = s.charAt(count++);
        if (c == smallest) {
            result += c;
        } else if (c == largest) {
            result += c;
        }
    }

    for (int i = s.length() - 1; i >= 0; i--) {
        char c = s.charAt(i);
        if (c == largest) {
            result += c;
        } else if (c == smallest) {
            result += c;
        }
    }

    return result;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();
    int i = 0, j = chars.length - 1;
    while (i <= j) {
        result.append(chars[i++]);
        result.append(chars[j--]);
    }
    return result.toString();
}

public String sortString(String s) {
    // Check if the input string is null or empty
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Initialize variables
    char smallestChar = ' ';
    char largestChar = ' ';
    int smallestIndex = -1;
    int largestIndex = -1;
    StringBuilder result = new StringBuilder();

    // Loop through the input string
    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);

        // Check if the current character is the smallest character
        if (currentChar < smallestChar) {
            smallestChar = currentChar;
            smallestIndex = i;
        }

        // Check if the current character is the largest character
        if (currentChar > largestChar) {
            largestChar = currentChar;
            largestIndex = i;
        }
    }

    // If the smallest character is found, add it to the result
    if (smallestIndex != -1) {
        result.append(s.charAt(smallestIndex));
    }

    // If the largest character is found, add it to the result
    if (largestIndex != -1) {
        result.append(s.charAt(largestIndex));
    }

    // Loop through the input string again and add all other characters to the result
    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar != smallestChar && currentChar != largestChar) {
            result.append(currentChar);
        }
    }

    // Return the sorted string
    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    // Step 1: Create a PriorityQueue to keep the smallest characters
    PriorityQueue<Character> queue = new PriorityQueue<>();
    for (char c : s.toCharArray()) {
        queue.add(c);
    }

    // Step 2: Re-order the string using the algorithm
    StringBuilder result = new StringBuilder();
    while (!queue.isEmpty()) {
        char min = queue.poll();
        result.append(min);

        // Step 3: If the smallest character appears more than once, pick it and append it to the result
        while (!queue.isEmpty() && min == queue.peek()) {
            char min1 = queue.poll();
            result.append(min1);
        }

        // Step 4: Pick the largest character and append it to the result
        char max = queue.peek();
        result.append(max);

        // Step 5: If the largest character appears more than once, pick it and append it to the result
        while (!queue.isEmpty() && max == queue.peek()) {
            char max1 = queue.poll();
            result.append(max1);
        }
    }

    return result.toString();
}

public String sortString(String s) {
    List<Character> sortedChars = new ArrayList<>();
    Set<Character> unusedChars = new HashSet<>(s.toCharArray());

    while (!unusedChars.isEmpty()) {
        Character smallestChar = unusedChars.iterator().next();
        Character largestChar = smallestChar;

        sortedChars.add(smallestChar);
        unusedChars.remove(smallestChar);

        while (!unusedChars.isEmpty()) {
            Character nextSmallestChar = unusedChars.iterator().next();
            if (nextSmallestChar > smallestChar) {
                sortedChars.add(nextSmallestChar);
                unusedChars.remove(nextSmallestChar);
                smallestChar = nextSmallestChar;
            } else {
                break;
            }
        }

        while (!unusedChars.isEmpty()) {
            Character nextLargestChar = unusedChars.iterator().next();
            if (nextLargestChar < largestChar) {
                sortedChars.add(nextLargestChar);
                unusedChars.remove(nextLargestChar);
                largestChar = nextLargestChar;
            } else {
                break;
            }
        }
    }

    return sortedChars.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    double average = (double) sum / nums.length;
    for (int i = 0; i < nums.length - 1; i++) {
        int leftSum = 0;
        for (int j = 0; j <= i; j++) {
            leftSum += nums[j];
        }
        int rightSum = sum - leftSum;
        if (Math.abs(leftSum - rightSum) / (nums.length - i - 1) == Math.abs(average)) {
            return true;
        }
    }
    return false;
}

