    double average = (double) sum / nums.length;
    for (int i = 1; i < nums.length; i++) {
        int leftSum = 0;
        for (int j = 0; j < i; j++) {
            leftSum += nums[j];
        }
        int rightSum = sum - leftSum;
        if (Math.abs((double) leftSum / i - average) < 1e-6 && Math.abs((double) rightSum / (nums.length - i)) < 1e-6) {
            return true;
        }
    }
    return false;
}

