public boolean hasAllCodes(String s, int k) {
    String[] allSubstrings = new String[s.length() - k + 1];
    for (int i = 0; i < s.length() - k + 1; i++) {
        allSubstrings[i] = s.substring(i, i + k);
    }
    for (String substring : allSubstrings) {
        if (!s.contains(substring)) {
            return false;
        }
    }
    return true;
}

public static boolean hasAllCodes(String s, int k) {
    // Initialize a set to store all binary strings of length k
    Set<String> set = new HashSet<>();

    // Loop through each substring of length k in s
    for (int i = 0; i <= s.length() - k; i++) {
        // If the substring is not already in the set, add it
        if (!set.contains(s.substring(i, i + k))) {
            set.add(s.substring(i, i + k));
        }
    }

    // Return true if the set contains all binary strings of length k, false otherwise
    return set.size() == (1 << k);
}

