public int minOperations(int n) {
    // Initialize a variable to keep track of the minimum number of operations
    int minOps = Integer.MAX_VALUE;
    // Initialize an array to store the elements of the array
    int[] arr = new int[n];
    // Initialize a variable to store the maximum value in the array
    int maxValue = arr[0];

    // Loop through the array and find the maximum value
    for (int i = 1; i < n; i++) {
        maxValue = Math.max(arr[i], maxValue);
    }

    // Loop through the array again and subtract the maximum value from each element
    // This will make all elements in the array equal
    for (int i = 0; i < n; i++) {
        arr[i] -= maxValue;
    }

    // Loop through the array and calculate the number of operations required to make all elements equal
    for (int i = 0; i < n; i++) {
        minOps = Math.min(minOps, arr[i]);
    }

    // Return the minimum number of operations required to make all elements equal
    return minOps;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    int currentMin = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        int min = Math.min(arr[i], arr[n - 1 - i]);
        if (min < currentMin) {
            currentMin = min;
            minOperations++;
        }
    }
    return minOperations;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    while (!isEqual(arr)) {
        int x = selectX(arr);
        int y = selectY(arr);
        arr[x] -= 1;
        arr[y] += 1;
        minOperations++;
    }
    return minOperations;
}

private boolean isEqual(int[] arr) {
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] != arr[0]) {
            return false;
        }
    }
    return true;
}

private int selectX(int[] arr) {
    int max = arr[0];
    int x = 0;
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] > max) {
            max = arr[i];
            x = i;
        }
    }
    return x;
}

private int selectY(int[] arr) {
    int min = arr[0];
    int y = 0;
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] < min) {
            min = arr[i];
            y = i;
        }
    }
    return y;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] == arr[j]) {
                break;
            }
            if (arr[i] > arr[j]) {
                minOperations++;
                arr[j] += arr[i] - arr[j];
            } else {
                minOperations++;
                arr[i] += arr[j] - arr[i];
            }
        }
    }
    return minOperations;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    for (int i = 0; i < n; i++) {
        int diff = arr[i] - arr[n - 1];
        if (diff < 0) {
            diff = -diff;
        }
        minOperations += diff;
    }
    return minOperations;
}

