public String makeGood(String s) {
    // check if the string is already "good"
    if (s.equals("")) {
        return s;
    }

    // check if the string contains any adjacent letters with opposite case
    for (int i = 0; i < s.length() - 1; i++) {
        char current = s.charAt(i);
        char next = s.charAt(i + 1);

        if (Character.isLowerCase(current) && Character.isUpperCase(next) ||
                Character.isUpperCase(current) && Character.isLowerCase(next)) {
            s = s.substring(0, i) + s.substring(i + 1);
            return makeGood(s);
        }
    }

    return s;
}

public String makeGood(String s) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (Character.isUpperCase(c)) {
            result.append(Character.toLowerCase(c));
        } else if (Character.isLowerCase(c)) {
            boolean foundMatch = false;
            for (int j = i + 1; j < s.length(); j++) {
                char nextChar = s.charAt(j);
                if (Character.isUpperCase(nextChar) && Character.toLowerCase(nextChar) == c) {
                    foundMatch = true;
                    break;
                }
            }
            if (!foundMatch) {
                result.append(c);
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

