public String getSmallestString(int n, int k) {
    char[] chars = new char[n];
    int remainder = k;
    for (int i = n - 1; i >= 0; i--) {
        int charValue = remainder % 27;
        char charCode = (char)('a' + charValue);
        chars[i] = charCode;
        remainder /= 27;
    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    // Initialize the string with the character at position k % 26
    String str = String.valueOf((char) (k % 26 + 'a'));

    // Loop through the remaining characters to fill in the string
    for (int i = 1; i < n; i++) {
        // Calculate the position of the next character based on the current value of k and the size of the alphabet
        int pos = (k / 26) % 26;
        char c = (char) (pos + 'a');
        str += c;
        k -= pos;
    }

    return str;
}

public String getSmallestString(int n, int k) {
    if (n < 1 || k < 1) {
        throw new IllegalArgumentException("n and k must be positive integers");
    }
    if (n > 26) {
        throw new IllegalArgumentException("n must be less than or equal to 26");
    }
    if (k > (26 * n)) {
        throw new IllegalArgumentException("k must be less than or equal to 26 * n");
    }
    String smallestString = "";
    int currentValue = 0;
    for (int i = 0; i < n; i++) {
        char smallestChar = 'a';
        for (int j = 0; j < 26; j++) {
            char currentChar = (char) ('a' + j);
            if (currentValue + j <= k) {
                smallestChar = currentChar;
                break;
            }
        }
        smallestString += smallestChar;
        currentValue += smallestChar - 'a' + 1;
    }
    return smallestString;
}

public String getSmallestString(int n, int k) {
    // Create a StringBuilder to hold the string
    StringBuilder sb = new StringBuilder(n);

    // Initialize the current character to 'a'
    char currentChar = 'a';

    // Loop until we have reached the desired length
    while (sb.length() < n) {
        // Add the current character to the string
        sb.append(currentChar);

        // Increment the value of the string
        k -= (currentChar - 'a' + 1);

        // Move to the next character
        currentChar++;

        // If we have reached the end of the alphabet, wrap around to 'a'
        if (currentChar > 'z') {
            currentChar = 'a';
        }
    }

    // Return the string
    return sb.toString();
}

public static String getSmallestString(int n, int k) {
    // Initialize the result string with the first character 'a'
    String result = "a";

    // Calculate the remaining length of the result string
    int remainingLength = n - 1;

    // Calculate the remaining value of the result string
    int remainingValue = k - 1;

    // Iterate until the remaining length is 0
    while (remainingLength > 0) {
        // Get the character with the lowest value that is still available
        char nextChar = getNextAvailableCharacter(result, remainingValue);

        // Add the next character to the result string
        result += nextChar;

        // Decrease the remaining length and value
        remainingLength--;
        remainingValue -= nextChar - 'a' + 1;
    }

    return result;
}

private static char getNextAvailableCharacter(String result, int remainingValue) {
    // Calculate the maximum value of the next available character
    int maxValue = Math.min(remainingValue, 26);

    // Iterate from the first character to the last character
    for (char c = 'a'; c <= 'z'; c++) {
        // Check if the current character is available
        if (result.indexOf(c) == -1 && c - 'a' + 1 <= maxValue) {
            // Return the first available character that meets the condition
            return c;
        }
    }

    // If no available character is found, throw an exception
    throw new IllegalArgumentException("No available character found for " + remainingValue);
}

