public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int currLength = 1;
                int left = j - 1;
                int right = j + 1;
                int up = i - 1;
                int down = i + 1;
                while (left >= 0 && mat[i][left] == 1) {
                    currLength++;
                    left--;
                }
                while (right < n && mat[i][right] == 1) {
                    currLength++;
                    right++;
                }
                while (up >= 0 && mat[up][j] == 1) {
                    currLength++;
                    up--;
                }
                while (down < m && mat[down][j] == 1) {
                    currLength++;
                    down++;
                }
                maxLength = Math.max(maxLength, currLength);
            }
        }
    }
    return maxLength;
}

public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[i].length; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 1;
                int[][] visited = new int[mat.length][mat[i].length];
                visited[i][j] = 1;
                currentLength = dfs(mat, i, j, visited, currentLength);
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }
    return maxLength;
}

private static int dfs(int[][] mat, int i, int j, int[][] visited, int currentLength) {
    if (i < 0 || i >= mat.length || j < 0 || j >= mat[i].length || visited[i][j] == 1 || mat[i][j] == 0) {
        return currentLength;
    }
    visited[i][j] = 1;
    currentLength++;
    dfs(mat, i + 1, j, visited, currentLength);
    dfs(mat, i - 1, j, visited, currentLength);
    dfs(mat, i, j + 1, visited, currentLength);
    dfs(mat, i, j - 1, visited, currentLength);
    return currentLength;
}

