public static boolean isBoomerang(int[][] points) {

        // Find the center point of the three points
        int centerX = (points[0][0] + points[1][0] + points[2][0]) / 3;
        int centerY = (points[0][1] + points[1][1] + points[2][1]) / 3;

        // Calculate the difference between the center and each point
        int[][] differences = new int[3][2];
        for (int i = 0; i < 3; i++) {
            differences[i][0] = centerX - points[i][0];
            differences[i][1] = centerY - points[i][1];
        }

        // Calculate the dot product of the differences
        int dotProduct = 0;
        for (int i = 0; i < 3; i++) {
            dotProduct += differences[i][0] * differences[i][1];
        }

        // Check if the dot product is zero
        if (dotProduct == 0) {
            return true;
        } else {
            return false;
        }
    }

