    // Check if the points form a straight line
    if (points.length < 3) {
        return false;
    }

    // Compute the slope between the first two points
    float slope1 = (float) (points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);

    // Check if the slope is the same for all other points
    for (int i = 2; i < points.length; i++) {
        float slope2 = (float) (points[i][1] - points[i - 1][1]) / (points[i][0] - points[i - 1][0]);
        if (slope1 != slope2) {
            return false;
        }
    }

    return true;
}

public static boolean isBoomerang(int[][] points) {
    // Check if the points form a straight line
    if (points.length < 3) {
        return false;
    }

    // Calculate the slope and y-intercept of the first two points
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    double slope = (double) (y2 - y1) / (x2 - x1);
    double yIntercept = y1 - slope * x1;

    // Check if the remaining points lie on the same line
    for (int i = 2; i < points.length; i++) {
        x1 = points[i][0];
        y1 = points[i][1];
        double newYIntercept = y1 - slope * x1;
        if (newYIntercept != yIntercept) {
            return false;
        }
    }

    // Check if the line passes through the origin
    if (slope != 0) {
        x1 = 0;
        y1 = yIntercept;
        for (int i = 0; i < points.length; i++) {
            x2 = points[i][0];
            y2 = points[i][1];
            if (x1 * y2 - y1 * x2 != 0) {
                return false;
            }
        }
    }

    return true;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    return (x2 - x1) * (y3 - y1) == (x3 - x1) * (y2 - y1);
}

