public static int calculateEnergy(String s) {
    int energy = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c != '\0') {
            int j = i + 1;
            while (j < s.length() && s.charAt(j) == c) {
                j++;
            }
            energy = Math.max(energy, j - i);
            i = j;
        }
    }
    return energy;
}

public static int calculateEnergy(String s) {
    int energy = 0;
    int currentSubstringLength = 0;
    char currentCharacter = s.charAt(0);

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == currentCharacter) {
            currentSubstringLength++;
        } else {
            if (currentSubstringLength > energy) {
                energy = currentSubstringLength;
            }
            currentSubstringLength = 1;
            currentCharacter = c;
        }
    }

    if (currentSubstringLength > energy) {
        energy = currentSubstringLength;
    }

    return energy;
}

