public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueSet = new HashSet<>();
    for (int num : nums) {
        if (!uniqueSet.contains(num)) {
            uniqueSet.add(num);
        }
    }
    int sum = 0;
    for (int uniqueInt : uniqueSet) {
        sum += uniqueInt;
    }
    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    return Arrays.stream(nums)
            .distinct()
            .sum();
}

public static int minPerfectSquareSum(int n) {
    int minSquares = n;
    for (int i = 1; i <= n; i++) {
        int j = n - i * i;
        if (j == 0) {
            minSquares = i;
            break;
        } else if (j > 0) {
            minSquares = Math.min(minSquares, minPerfectSquareSum(j) + 1);
        }
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n+1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int j = 1; j*j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i-j*j] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
  // Initialize a list to store the perfect square numbers
  List<Integer> perfectSquares = new ArrayList<>();

  // Loop through the squares of integers until the sum is greater than or equal to n
  for (int i = 1; i * i <= n; i++) {
    // Add the current perfect square to the list
    perfectSquares.add(i * i);
  }

  // Initialize a variable to store the minimum number of perfect squares
  int minNumPerfectSquares = Integer.MAX_VALUE;

  // Loop through the combinations of perfect squares
  for (int i = 0; i < perfectSquares.size(); i++) {
    for (int j = i; j < perfectSquares.size(); j++) {
      // Check if the current combination sums up to n
      if (perfectSquares.get(i) + perfectSquares.get(j) == n) {
        // Update the minimum number of perfect squares
        minNumPerfectSquares = Math.min(minNumPerfectSquares, 2);
        break;
      }
    }
  }

  // Return the minimum number of perfect squares
  return minNumPerfectSquares;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        count++;
        n -= root * root;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    int i = 1;
    while (n > 0) {
        int square = i * i;
        if (square <= n) {
            n -= square;
            count++;
        } else {
            i++;
        }
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        char[] chars = words[i].toCharArray();
        for (int j = 0; j < chars.length / 2; j++) {
            char temp = chars[j];
            chars[j] = chars[chars.length - j - 1];
            chars[chars.length - j - 1] = temp;
        }
        words[i] = new String(chars);
    }
    return String.join(" ", words);
}

public static String reverseWords(String s) {
    StringBuilder sb = new StringBuilder();
    String[] words = s.split(" ");
    for (String word : words) {
        sb.append(new StringBuffer(word).reverse().toString() + " ");
    }
    return sb.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        char[] chars = words[i].toCharArray();
        int left = 0;
        int right = chars.length - 1;
        while (left < right) {
            char temp = chars[left];
            chars[left] = chars[right];
            chars[right] = temp;
            left++;
            right--;
        }
        words[i] = new String(chars);
    }
    return String.join(" ", words);
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
        result.append(new StringBuilder(word).reverse().toString() + " ");
    }
    return result.toString().trim();
}

